export function AgentActivity({
  latestAction = "{{latestAction}}",
  density = "{{density}}",
  accent = "{{accent}}",
  showTimestamps = {{showTimestamps}},
}) {
  const rowPad = density === "compact" ? "5px 0" : "10px 0";
  const rowGap = density === "compact" ? 8 : 10;
  const fontSize = density === "compact" ? 12.5 : 14;
  const rows = [
    { text: latestAction, code: null, time: "just now" },
    { text: "Read file ", code: "config.json", time: "2 min ago" },
    { text: "Ran test suite", code: null, time: "6 min ago" },
  ];
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 360, padding: 16, borderRadius: 12, border: "1px solid #24143014", boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".05em", color: "#24143099" }}>Agent activity</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {rows.map((row, i) => (
          <li key={row.time} style={{ display: "flex", alignItems: "baseline", gap: rowGap, padding: rowPad,
            borderBottom: i < rows.length - 1 ? "1px solid #24143014" : "none" }}>
            <span aria-hidden="true" style={{ flex: "none", width: 7, height: 7, borderRadius: "50%", background: accent, alignSelf: "center" }} />
            <span style={{ flex: 1 }}>{row.text}{row.code && <code style={{ background: "#24143012", padding: "0.1em 0.35em", borderRadius: 4, fontSize: "0.92em" }}>{row.code}</code>}</span>
            {showTimestamps && <time style={{ flex: "none", fontSize: 12, color: "#24143099", whiteSpace: "nowrap" }}>{row.time}</time>}
          </li>
        ))}
      </ul>
    </section>
  );
}
